SINA_SMART["embryo1-gametogenesis"] = {"lecture":"embryo1-gametogenesis","title":"Gametogenesis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"embryo1-gametogenesis:s0","text":"Describe and explain: Embryology and human ontogeny","topic":"Embryology and human ontogeny","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e0","text":"Somatic cells: mitosis, diploid (46); gametes: meiosis, haploid (23).","topic":"Mitosis versus meiosis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e1","text":"Meiosis I separates homologues (crossing-over); meiosis II separates sister chromatids.","topic":"Mitosis versus meiosis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e2","text":"Spermatogenesis starts at puberty in seminiferous tubules; sperm mature in the epididymis.","topic":"Spermatogenesis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e3","text":"Spermatogonia → primary spermatocyte (2n, 4N) → secondary (n) → spermatid → spermatozoon.","topic":"Spermatogenesis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e4","text":"Spermiogenesis: no division; acrosome, condensed nucleus, flagellum, cytoplasm lost to Sertoli cells.","topic":"Spermatogenesis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e5","text":"Oogonia multiply only before birth; primary oocytes arrest in prophase I.","topic":"Oogenesis and follicles","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e6","text":"Follicles: primordial → primary → secondary → Graafian (antrum).","topic":"Oogenesis and follicles","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e7","text":"Meiosis I completed just before ovulation; secondary oocyte arrests at metaphase II until fertilisation.","topic":"Oogenesis and follicles","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e8","text":"One ovum + polar bodies per oocyte; four sperm per spermatocyte.","topic":"Oogenesis and follicles","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"embryo1-gametogenesis:e9","text":"Capacitation (5-7 h) enables the acrosome reaction; fertilisation in the ampulla.","topic":"Sperm transport, capacitation and the acrosome reaction","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1pu6uyi":"a","8vhakp":"a","1nacwsl":"a","nd5khg":"a","1l6ta3m":"a","kw4o4d":"a","c8cdae":"a","dct1mu":"a","uvrgr8":"a","el97x3":"a","1rhd2y4":"a","8ah3fq":"a","11dkx6j":"a","19qh2rb":"a","7pf1s0":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"embryo1-gametogenesis:s0":{"s":0,"u":["Embryology studies development from the fertilisation of a female gamete by a male gamete through the growth and differentiation that build a complex, independent organism.","Ontogeny (life cycle) runs from fertilisation to death: the prenatal period (fertilisation to delivery) and the postnatal period (delivery to death)."],"dp":[]},"embryo1-gametogenesis:e0":{"s":1,"u":["Somatic cells: mitosis, diploid (46); gametes: meiosis, haploid (23).","Mitosis gives two identical diploid cells .","The somatic cell cycle: G1 (growth, biosynthesis), S (DNA replication), G2 (preparation), M (mitosis and cytokinesis); G0 is a resting state."],"dp":[]},"embryo1-gametogenesis:e1":{"s":1,"u":["Meiosis I separates homologues (crossing-over); meiosis II separates sister chromatids.","Meiosis II : the centromeres divide and sister chromatids separate , like mitosis.","Meiosis I : homologous chromosomes pair into tetrads, exchange segments by crossing-over at chiasmata, and separate (reductional division)."],"dp":[]},"embryo1-gametogenesis:e2":{"s":2,"u":["Spermatogenesis starts at puberty in seminiferous tubules; sperm mature in the epididymis.","Starts at puberty in the seminiferous tubules (250-1000 per testis); sperm become motile and able to fertilise in the epididymis , where they are stored.","Route: seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct."],"dp":[]},"embryo1-gametogenesis:e3":{"s":2,"u":["Spermatogonia → primary spermatocyte (2n, 4N) → secondary (n) → spermatid → spermatozoon.","Cells, from basal lamina to lumen: spermatogonia (type A stem cells, type B committed) → primary spermatocytes (2n, 4N DNA, largest, prophase I about 22 days) → secondary spermatocytes (n, 2N, short-lived) → spermatids (n, 1N, 7-8 µm) → spermatozoa ."],"dp":[]},"embryo1-gametogenesis:e4":{"s":2,"u":["Spermiogenesis: no division; acrosome, condensed nucleus, flagellum, cytoplasm lost to Sertoli cells.","Spermiogenesis is the final transformation, with no division: acrosome formation, condensation and elongation of the nucleus, flagellum, mitochondria arranged along the axoneme, and loss of cytoplasm as residual bodies phagocytosed by Sertoli cells ."],"dp":[]},"embryo1-gametogenesis:e5":{"s":3,"u":["Oogonia multiply only before birth; primary oocytes arrest in prophase I.","Before birth , oogonia multiply by mitosis, then enter meiosis I and stop in prophase I as primary oocytes , each wrapped in flat granulosa cells: the primordial follicle .","Just before ovulation, the primary oocyte completes meiosis I asymmetrically: a large secondary oocyte and a small first polar body ."],"dp":[{"h":"Why maternal age raises the risk of trisomy","t":"Primary oocytes enter meiosis I before birth and wait in prophase I until the month they ovulate, up to 40-50 years later. During that long pause the cohesion that holds homologues together weakens, so at ovulation a pair is more likely to fail to separate ( non-disjunction ). A secondary oocyte carrying an extra chromosome 21, fertilised by a normal sperm, gives trisomy 21. Sperm, made continuously from puberty, do not have this long arrest, which is why the risk rises mainly with the mother's age. Source: the lecture's timeline of oogenesis; standard link to non-disjunction."}]},"embryo1-gametogenesis:e6":{"s":3,"u":["Follicles: primordial → primary → secondary → Graafian (antrum).","After puberty, follicles mature: primary follicle (cuboidal granulosa, basement membrane, zona pellucida appears), secondary follicle (fluid-filled vesicles, theca, corona radiata), mature (Graafian) follicle with a single antrum , cumulus oophorus, theca interna and externa.","Before birth , oogonia multiply by mitosis, then enter meiosis I and stop in prophase I as primary oocytes , each wrapped in flat granulosa cells: the primordial follicle ."],"dp":[]},"embryo1-gametogenesis:e7":{"s":3,"u":["Meiosis I completed just before ovulation; secondary oocyte arrests at metaphase II until fertilisation.","Just before ovulation, the primary oocyte completes meiosis I asymmetrically: a large secondary oocyte and a small first polar body .","The secondary oocyte starts meiosis II and stops at metaphase II ; it completes it (with a second polar body) only if fertilised ."],"dp":[]},"embryo1-gametogenesis:e8":{"s":3,"u":["One ovum + polar bodies per oocyte; four sperm per spermatocyte.","Oogenesis gives one ovum per meiosis and has no metamorphosis stage; spermatogenesis gives four sperm.","Just before ovulation, the primary oocyte completes meiosis I asymmetrically: a large secondary oocyte and a small first polar body ."],"dp":[]},"embryo1-gametogenesis:e9":{"s":4,"u":["Capacitation (5-7 h) enables the acrosome reaction; fertilisation in the ampulla.","Fertilisation usually takes place in the uterine tube (ampulla).","It allows the acrosome reaction : the outer acrosomal membrane fuses with the plasma membrane, releasing enzymes to cross the zona pellucida."],"dp":[]}},"meta":{"1pu6uyi":{"a":"recall","vg":"embryo1-gametogenesis:e0/recall/1"},"8vhakp":{"a":"recall","vg":"embryo1-gametogenesis:e1/recall/1"},"1nacwsl":{"a":"recall","vg":"embryo1-gametogenesis:e1/recall/2"},"nd5khg":{"a":"recall","vg":"embryo1-gametogenesis:e2/recall/1"},"1l6ta3m":{"a":"recall","vg":"embryo1-gametogenesis:e2/recall/2"},"kw4o4d":{"a":"recall","vg":"embryo1-gametogenesis:e3/recall/1"},"c8cdae":{"a":"recall","vg":"embryo1-gametogenesis:e4/recall/1"},"dct1mu":{"a":"recall","vg":"embryo1-gametogenesis:e4/recall/2"},"uvrgr8":{"a":"recall","vg":"embryo1-gametogenesis:e5/recall/1"},"el97x3":{"a":"recall","vg":"embryo1-gametogenesis:e7/recall/1"},"1rhd2y4":{"a":"recall","vg":"embryo1-gametogenesis:e6/recall/1"},"8ah3fq":{"a":"recall","vg":"embryo1-gametogenesis:e8/recall/1"},"11dkx6j":{"a":"recall","vg":"embryo1-gametogenesis:e9/recall/1"},"19qh2rb":{"a":"recall","vg":"embryo1-gametogenesis:e9/recall/2"},"7pf1s0":{"a":"recall","vg":"embryo1-gametogenesis:e9/recall/3"}},"explRev":"5d34b519a701"};
